/* Week 2 is an additive, saved quest. Nothing in this file activates in Week 1. */
const week2Endings={
 face:['Ending 39 · A face returned','You lift the stolen face onto the mannequin. It exhales a name that is not yours.\nAcross the city, every borrowed face falls away. A woman steps out of the shop window and thanks you for remembering where she belonged.\nAt home, Mother recognises you before you speak.'],
 rescue:['Ending 40 · Someone on the other side','You knock three times and speak Ada’s name. The impossible door opens onto a cramped, ordinary cupboard.\nA frightened woman takes the sweet you offer. Together, you walk into the morning. Behind you, a whole street of locked doors begins to open.'],
 neighbour:['Ending 41 · Everybody’s neighbour','You leave three sweets on the impossible doorstep and put on the neighbour’s mask. Every curtain in the city opens.\nThey remember your birthday. They remember your childhood. They remember you living here before the street was built.\nMother passes your house each morning. You always wave. She never comes in.']
};
const week2Doors=['station','library','cinema','clinic','chapel','workshop'];
function week2Active(){return typeof releaseAccess!=='undefined'&&releaseAccess==='week2';}
function week2State(){const h=halloweenState();if(!h.week2)h.week2={visited:[],resolved:[],clues:[],mask:null,owned:['crow','moth','neighbour'],worn:0,elapsed:0,nextScare:24,sequence:0,seen:[],parcel:false,delivered:false,key:false,windingKey:false,repaired:false,basementRead:false,face:false,faceReturned:false,rescueReady:false,offered:false,extraHouse:false,mannequin:0,mannequinAt:0};return h.week2;}
const week2Runtime={effect:null,at:0,shadow:null,last:null,pressure:0};
const week2Masks={crow:'The crow mask',moth:'The moth mask',neighbour:'The neighbour’s mask'};
function week2Tell(title,text,damage=0,actions=[['Step away',close]]){modal(title,text,actions);if(damage)queueSanity(damage);}
function week2Remember(id){const w=week2State();if(!w.resolved.includes(id))w.resolved.push(id);save();render();}
function week2Clue(id){let w=week2State();if(!w.clues.includes(id))w.clues.push(id);}
function week2DoorPosition(id){const c=cityWorld().find(c=>c.id===id);return [c.x+3,1.15,c.z+4.24];}
function week2Knock(id){
 if(!week2Active()||!week2Doors.includes(id)||s.ending||s.sanityLost)return;
 const w=week2State(),h=halloweenState(),first=!w.visited.includes(id);if(first)w.visited.push(id);save();
 if(id==='station'){
  const taken=w.resolved.includes(id),recognised=w.mask==='neighbour';
  return week2Tell('The porter’s doorstep',recognised?'“Our neighbour! You have always lived here.” He remembers a birthday you have never celebrated.':'“Two sweets for a face I recognise,” says the porter. A neighbour’s mask would convince him.',0,[
   ...(!taken?[['Accept two wrapped sweets',()=>{if(w.resolved.includes(id))return;h.candy+=2;week2Remember(id);week2Tell('TREAT · Two warm sweets','The porter points east, through the gap in the city wall. “Velvet & Ash still has masks. Take yours off before the procession learns your shape.”');}]]:[]),
   ...(recognised?[['Ask who lived in the extra house',()=>{week2Clue('neighbour');save();week2Tell('A familiar address','“Leave three sweets at the extra house. Then introduce yourself as our neighbour. We will take care of the rest.”');}]]:[]),['Goodnight',close]]);
 }
 if(id==='library'){
  week2Remember(id);week2Clue('mother');save();if(first){week2Scare('bell');return week2Tell('Mother answers from inside','“You forgot your key, darling.”\nIt is Mother’s voice. Your house is on the other side of the city.\nA bell rings behind you. The doorway is empty when you turn.',6);}
  return week2Tell('A voice that knows you','“I can wait all night,” Mother’s voice says. “Find the receipt at Velvet & Ash. It tells you whose face was taken.”');
 }
 if(id==='cinema'){
  if(w.delivered)return week2Tell('The projectionist remembers','The basement key is already in your pocket. “The parcel came from the Dead Letter Office. Do not open another one.”');
  return week2Tell('The projectionist’s errand',w.mask==='crow'?'“A courier. Good. Have you brought my parcel?”':'“There is a parcel for me at the Dead Letter Office. Bring it here and I will lend you the costume shop’s basement key.”',0,[
   ...(w.parcel?[['Deliver the misaddressed parcel',()=>{if(w.delivered||!w.parcel)return;w.parcel=false;w.delivered=true;w.key=true;h.candy+=2;week2Remember(id);week2Tell('TREAT · A brass basement key','The parcel rattles once. The projectionist gives you two sweets and a key marked VELVET & ASH.\n“The hatch at the back of the shop. If the mannequin moves, do not follow it.”',3);}]]:[]),['Keep looking',close]]);
 }
 if(id==='clinic'){
  if(w.resolved.includes(id))return week2Tell('An empty bowl','The bowl holds only black wrappers. You remember the taste.');
  return week2Tell('The nurse’s bowl',w.mask==='moth'?'The nurse lowers her bowl. “That mask sees through wrapping paper. Take the safe sweet beneath it.”':'“Something sweet for the journey,” says the nurse. The wrappers twitch.',0,[
   ['Choose a sweet',()=>{if(w.resolved.includes(id))return;week2Remember(id);if(w.mask==='moth'){h.candy++;save();week2Tell('TREAT · The hidden sweet','Your moth mask reveals which wrapper is empty of shadows. One safe sweet goes into your pocket.');}else week2Tell('TRICK · A mouthful of ash','The sweet becomes cold ash against your tongue. Somewhere inside the clinic, a child laughs in your voice.\nThe moth mask would have revealed the trick.',7);} ],['Leave the bowl',close]]);
 }
 if(id==='chapel'){
  week2Remember(id);week2Clue('knocks');save();return week2Tell('The woman behind the chapel door',w.mask==='moth'?'“You can hear her too. Ada is behind the house that should not exist. Three knocks, her name, and something sweet. The basement receipt will tell you the name.”':'“There is someone behind the extra house’s door. Wear the moth mask when you answer. Three knocks, then speak her real name. A sweet will help her trust you.”',first?3:0);
 }
 if(id==='workshop'){
  if(w.repaired)return week2Tell('The clockmaker’s thanks','The repaired clock counts your footsteps. “Return the stolen face to the mannequin. Wear the crow mask so it knows you are bringing something back.”');
  return week2Tell('The clockmaker’s task','“My winding key is on the costume shop counter. Bring it back. I can tell you what the mannequin is missing.”',0,[
   ...(w.windingKey?[['Return the winding key',()=>{if(w.repaired)return;w.repaired=true;w.windingKey=false;h.candy+=2;week2Clue('return');week2Remember(id);week2Tell('TREAT · The clock starts backwards','Two sweets. One instruction: “The face belongs to the mannequin. Find it in the locked basement, then return it wearing the crow mask.”');}]]:[]),['Look for the key',close]]);
 }
}
function week2Parcel(){if(!week2Active())return;const w=week2State();if(w.delivered)return week2Tell('An empty pigeonhole','The projectionist has the parcel.');if(w.parcel)return week2Tell('Already in your pocket','Take the parcel to the cinema doorstep.');w.parcel=true;save();week2Tell('The misaddressed parcel','TO: THE PROJECTIONIST, ORPHEUM CINEMA.\nThe address beneath the label is your childhood home. The parcel is small enough to carry under one arm.',3);}
function week2Wardrobe(){if(!week2Active())return;let w=week2State();week2Tell('Velvet & Ash · Costume counter','Three masks hang beneath a sign: BORROW A FACE. RETURN IT BEFORE IT REMEMBERS YOU.\n\nCROW · Trusted by the keeper of stolen things.\nMOTH · Reveals false treats; lets a frightened voice trust you.\nNEIGHBOUR · The porter knows you. Everyone may learn your name.\n\nWorn: '+(week2Masks[w.mask]||'none')+' · '+Math.floor(w.worn)+' seconds. At 45 seconds the procession starts following.',0,[...Object.entries(week2Masks).map(([id,label])=>['Wear '+label.toLowerCase(),()=>week2Wear(id)]),...(w.mask?[['Remove mask',()=>week2Wear(null)]]:[]),['Step away',close]]);}
function week2Wear(id){if(!week2Active()||id&&!Object.hasOwn(week2Masks,id))return false;let w=week2State();w.mask=id;w.worn=0;week2Runtime.pressure=0;save();week2Tell(id?'A borrowed face':'Your own face',id?'The ribbon tightens behind your head. Take the mask off from WEEK 2 QUEST before 45 seconds if you want to avoid the procession.':'The footsteps behind you begin to fall out of step.');return true;}
function week2Key(){let w=week2State();if(!week2Active()||w.repaired||w.windingKey)return;w.windingKey=true;save();week2Tell('The clockmaker’s winding key','A tiny brass key rests between the masks. The clockmaker at Hollow Clock Repairs asked you to bring it back.');}
function week2Basement(){if(!week2Active())return;let w=week2State();if(!w.key)return week2Tell('The locked basement hatch','A brass lock marked VELVET & ASH. The projectionist at the cinema offers the key in exchange for a parcel.');week2Tell('The basement hatch','Cold air rises through the slats. A narrow ladder leads below the costume shop.',0,[['Unlock and climb down',()=>week2Travel('basement')],['Stay upstairs',close]]);}
function week2Receipt(){if(!week2Active())return;let w=week2State(),first=!w.basementRead;w.basementRead=true;week2Clue('ada');save();week2Tell('ALTERATION RECEIPT · ADA VALE','ONE FACE REMOVED. ONE VOICE STORED BEHIND A DOOR.\n\nReturn the face to its wooden owner in the shop, wearing the crow mask.\nOr answer Ada at the house that appears after the street begins to recognise you. Wear the moth mask. Knock three times. Give her one sweet.\n\nThe clockmaker remembers how the face was taken.',first?7:0);}
function week2Face(){if(!week2Active())return;let w=week2State();if(!w.basementRead)return week2Tell('A face under tissue paper','A label tells you to read the alteration receipt before touching it.');if(w.face)return week2Tell('A face in your pocket','The face is still warm. The mannequin upstairs is missing it.');w.face=true;save();week2Tell('The stolen face','The wax face smiles after you stop looking at it. Return it to the mannequin upstairs. The crow mask is the costume of a returning courier.',6);}
function week2Mannequin(){if(!week2Active())return;let w=week2State();week2Tell('A mannequin without a face',w.face?'Its empty head turns towards the face in your pocket. The clockmaker said to return it wearing the crow mask.':'Someone has removed its face. The winding key and a locked hatch are at the back of the shop.',0,[...(w.face?[['Return the stolen face',()=>{if(w.mask!=='crow'||!w.repaired)return week2Tell('The wooden hand closes','Wear the crow mask and ask the clockmaker how to return what was stolen.');week2Finish('face');}]]:[]),['Look away',close]]);}
function week2ExtraDoor(){if(!week2Active()||!week2State().extraHouse)return;let w=week2State(),h=halloweenState();week2Tell('The house that was not here','A woman is whispering behind the door. Every other window on the street is watching.\n\n'+(w.rescueReady?'Ada is ready to leave.':w.clues.includes('ada')?'You know her name: Ada Vale.':'You do not know the woman’s name. A receipt lies beneath the costume shop.'),0,[
 ['Knock three times and speak Ada’s name',()=>{if(w.mask!=='moth'||!w.clues.includes('ada')||!w.clues.includes('knocks'))return week2Tell('No answer','Find the basement receipt and the chapel’s instructions. Wear the moth mask when you knock.');if(h.candy<1)return week2Tell('Someone too frightened to leave','Bring one sweet to show her that you are real.');if(!w.rescueReady){h.candy--;w.rescueReady=true;save();}week2Tell('Ada answers','“I remember my name now.” The lock turns on the other side.',0,[['Open the door and lead Ada out',()=>week2Finish('rescue')],['Keep exploring',close]]);} ],
 ['Leave three sweets on the doorstep',()=>{if(w.offered)return week2Tell('The offering is waiting','Introduce yourself in the neighbour’s mask after visiting all six doors.');if(h.candy<3)return week2Tell('Not enough sweets','The doorstep has three empty circles.');h.candy-=3;w.offered=true;save();week2Tell('Three wrappers unfold','Every house on the street lights one window.');}],
 ['Introduce yourself as their neighbour',()=>{if(!week2Allowed('neighbour'))return week2Tell('They do not all remember you','Resolve all six door visits, ask the porter about this address wearing the neighbour’s mask, and leave three sweets here. Then return wearing the neighbour’s mask.');week2Finish('neighbour');}],['Step back',close]]);}
function week2Allowed(id){if(!week2Active()||s.ending||s.sanityLost)return false;let w=week2State();return id==='face'?w.face&&w.basementRead&&w.repaired&&w.mask==='crow':id==='rescue'?w.extraHouse&&w.rescueReady&&w.mask==='moth'&&w.clues.includes('ada')&&w.clues.includes('knocks'):id==='neighbour'?w.extraHouse&&w.offered&&w.mask==='neighbour'&&w.clues.includes('neighbour')&&week2Doors.every(id=>w.resolved.includes(id)):false;}
const week2PreviousEnding=ending;ending=function(id){if(!id.startsWith('week2:'))return week2PreviousEnding(id);let key=id.slice(6);if(!week2Endings[key]||!week2Allowed(key))return;s.ending={title:week2Endings[key][0],body:week2Endings[key][1]};save();showEnding();};
function week2Finish(id){if(!week2Allowed(id))return;week2Tell('Finish this Week 2 story?',week2Endings[id][0]+'\nThis ends this run and records the ending in your journal.',0,[['Choose this ending',()=>ending('week2:'+id)],['Keep exploring',close]]);}
function week2Travel(place){if(!week2Active())return false;let x,z,a=0,y=.1,room='city';if(place==='shop'){x=56;z=-29.5;a=Math.PI;room='costume_shop';}else if(place==='basement'){if(!week2State().key)return false;x=56;z=-34;a=Math.PI;y=-3.2;room='costume_basement';}else if(place==='extra'){if(!week2State().extraHouse)return false;x=56;z=-47.5;a=Math.PI;}else if(place==='parcel'){let c=cityWorld().find(c=>c.id==='postoffice');x=c.x+1.4;z=c.z-1;a=-Math.PI/2;y=0;}else if(week2Doors.includes(place)){let p=week2DoorPosition(place);x=p[0];z=p[2]+1.7;a=Math.PI;y=0;}else return false;s.cityOpen=true;house.x=x;house.z=z;house.a=a;house.pitch=0;house.jumpHeight=y;house.jumpVelocity=0;house.keys={};house.pointer=null;s.room=room;save();close();buildHouse();house.dirty=true;return true;}
function week2Journal(){if(!week2Active())return showReleaseEvent();let w=week2State();week2Tell('Week 2 · The Houses That Answer','The east passage beside the city’s second street leads to Velvet & Ash.\n\n'+week2Doors.map(id=>(w.resolved.includes(id)?'✓ ':'○ ')+cityPlaces.find(c=>c.id===id).name+' doorstep').join('\n')+'\n\nMask: '+(week2Masks[w.mask]||'none')+' · worn '+Math.floor(w.worn)+'s / 45s\nParcel: '+(w.delivered?'delivered':w.parcel?'carried':'at Dead Letter Office')+' · Basement key: '+(w.key?'found':'missing')+'\nClockmaker: '+(w.repaired?'helped':'needs winding key')+'\nBasement receipt: '+(w.basementRead?'read':'unread')+' · Stolen face: '+(w.face?'carried':'missing')+'\nExtra house: '+(w.extraHouse?'appeared':'will appear after two visits and 45 seconds of active play')+'\n\nTHREE PATHS\nReturn the stolen face · Lead Ada out · Become the remembered neighbour. These are separate endings; begin another run to find the others.',0,[['Velvet & Ash costume shop',()=>week2Travel('shop')],...week2Doors.map(id=>[cityPlaces.find(c=>c.id===id).name+' doorstep',()=>week2Travel(id)]),['Dead Letter Office parcel',()=>week2Travel('parcel')],...(w.extraHouse?[['The extra house',()=>week2Travel('extra')]]:[]),...(w.mask?[['Remove mask',()=>week2Wear(null)]]:[]),['Keep exploring',close]]);}
