function week2Scare(kind){if(!week2Active())return false;let w=week2State();if(!w.seen.includes(kind))w.seen.push(kind);let a=house.a+Math.PI;week2Runtime.effect={kind,time:0,x:house.x+Math.sin(a)*2.4,z:house.z+Math.cos(a)*2.4,y:supportAt(house.x,house.z)};if(kind==='bell'){tone(440,.2);setTimeout(()=>tone(330,.5),250);say('A doorbell rings behind you. There was no door there.');}if(kind==='shadow'){week2Runtime.shadow={x:house.x,z:house.z,y:supportAt(house.x,house.z),a:house.a,time:0};say('You stop. Your shadow takes another step.');}save();return true;}
function advanceWeek2(dt){if(!week2Active()||!s.started||paused()||s.ending||s.sanityLost)return;dt=Math.max(0,Math.min(.1,dt));let w=week2State();w.elapsed+=dt;
 if(w.mask){w.worn+=dt;if(w.worn>=45){week2Runtime.pressure+=dt;if(week2Runtime.pressure>=12){week2Runtime.pressure=0;drainSanity(4);say('The procession is following your borrowed face. Remove the mask from WEEK 2 QUEST.');}if(w.worn-dt<45)say('Forty-five seconds. The procession has found your mask. Remove it to lose them.');}}else week2Runtime.pressure=0;
 if(w.elapsed>=w.nextScare){week2Scare(w.sequence++%2?'shadow':'bell');w.nextScare=w.elapsed+({easy:65,intermediate:48,hard:32}[s.difficulty]||48);}
 const last=week2Runtime.last,moved=last&&Math.hypot(house.x-last.x,house.z-last.z)>.003;
 if(last&&last.moving&&!moved&&w.elapsed-(week2Runtime.lastShadowAt||0)>20){week2Scare('shadow');week2Runtime.lastShadowAt=w.elapsed;}
 week2Runtime.last={x:house.x,z:house.z,moving:!!moved};if(week2Runtime.effect){week2Runtime.effect.time+=dt;if(week2Runtime.effect.time>8)week2Runtime.effect=null;}if(week2Runtime.shadow){let sh=week2Runtime.shadow;sh.time+=dt;sh.x+=Math.sin(sh.a)*dt*.85;sh.z+=Math.cos(sh.a)*dt*.85;if(sh.time>3)week2Runtime.shadow=null;}
 if(!w.extraHouse&&w.visited.length>=2&&w.elapsed>=45){w.extraHouse=true;if(!w.seen.includes('house'))w.seen.push('house');buildHouse();save();say('There is an extra house beyond Velvet & Ash. You are certain the road ended there before.');}
 if(w.elapsed>=w.mannequinAt&&s.room==='costume_shop'){const p=week2MannequinPosition();if(!anomalyInView([p[0],1.4,p[1]])){w.mannequin=(w.mannequin+1)%3;w.mannequinAt=w.elapsed+12;save();say('Wooden feet scrape the shop floor.');}}
}
const week2PreviousMovement=updateMovement;updateMovement=function(dt){week2PreviousMovement(dt);advanceWeek2(dt);};
