const week2PreviousDisplay=halloweenDisplay;halloweenDisplay=function(){if(!week2Active())return week2PreviousDisplay();const w=week2State(),h=halloweenState(),remaining=Math.max(0,Math.ceil(90-h.elapsed));const text=(h.midnight?'MIDNIGHT':'MIDNIGHT IN '+Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0'))+' · SWEETS '+h.candy+'\n'+(w.mask?week2Masks[w.mask].toUpperCase()+' · '+Math.floor(w.worn)+'s'+(w.worn>=45?'\nTHE PROCESSION IS FOLLOWING':' / 45s'):'YOUR OWN FACE · NO MASK')+'\nDOOR TASKS '+w.resolved.length+'/6';if(halloweenHUD.textContent!==text)halloweenHUD.textContent=text;const objective=taskRows().find(t=>!t.done)?.label||'Choose a Week 2 ending.';if($('objective').textContent!==objective)$('objective').textContent=objective;};
